import os, glob, re

def load_grids():
    """Load all grids from the session log."""
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}

    # Find the session file
    base_name = os.path.basename(d)
    session_file = os.path.join(os.path.dirname(d), '..', 'sessions', base_name + '.jsonl')

    G = {}
    try:
        with open(session_file, 'r') as f:
            content = f.read()

        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows_content = content[m.end():].split('\n')[:h]
            rows = [r.split() for r in rows_content if r.strip()]

            # Validate and convert to ints
            valid = all(len(row) == w and len(row) > 0 and all(x.isdigit() for x in row) for row in rows)
            if valid:
                G[k] = [[int(x) for x in row] for row in rows]

    except FileNotFoundError:
        pass

    return G

G = load_grids()
print("Keys found:", sorted(G.keys()))
for k in sorted(G.keys())[:5]:
